import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_layout_elements(file_path: str):
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-layout", document=f)
        result = poller.result()

    layout_data = {
        "paragraphs": [],
        "lines": [],
        "tables": [],
        "selection_marks": []
    }

    for page in result.pages:
        for paragraph in page.paragraphs:
            br = paragraph.bounding_regions[0]
            layout_data["paragraphs"].append({
                "text": paragraph.content,
                "page_number": br.page_number,
                "polygon": br.polygon
            })

        for line in page.lines:
            br = line.bounding_regions[0]
            layout_data["lines"].append({
                "text": line.content,
                "page_number": br.page_number,
                "polygon": br.polygon
            })

        for mark in page.selection_marks:
            br = mark.bounding_regions[0]
            layout_data["selection_marks"].append({
                "state": mark.state,
                "page_number": br.page_number,
                "polygon": br.polygon
            })

    for table in result.tables:
        cells = []
        for cell in table.cells:
            cells.append({
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "content": cell.content,
                "is_header": cell.is_header
            })

        br = table.bounding_regions[0]
        layout_data["tables"].append({
            "row_count": table.row_count,
            "column_count": table.column_count,
            "page_number": br.page_number,
            "polygon": br.polygon,
            "cells": cells
        })

    return layout_data
